package weakpass6

import (
	"encoding/binary"
)

// BloomFilter checks membership of 6-character strings.
type BloomFilter struct {
	bits      []byte
	numHashes int
	numBits   int
}

// Load reads a Bloom filter from a binary blob generated by genweakpass6.
//
// Binary format:
//
//	[4 bytes big-endian uint32] number of hash functions k
//	[4 bytes big-endian uint32] number of bits m
//	[ceil(m/8) bytes]           bit array
func Load(data []byte) (*BloomFilter, error) {
	if len(data) < 8 {
		return nil, errCorrupt
	}
	k := int(binary.BigEndian.Uint32(data))
	m := int(binary.BigEndian.Uint32(data[4:]))
	expectedBytes := (m + 7) / 8
	if len(data) < 8+expectedBytes {
		return nil, errCorrupt
	}
	return &BloomFilter{
		bits:      data[8 : 8+expectedBytes],
		numHashes: k,
		numBits:   m,
	}, nil
}

// Contains reports whether the 6-character chunk might be in the set.
// Returns true for possible members (may have false positives) and
// false for definite non-members (no false negatives).
func (bf *BloomFilter) Contains(chunk string) bool {
	h := hash64(chunk)
	// Double hashing (Kirsch-Mitzenmacher): h1 + i*h2. Using the two halves of
	// a well-avalanched 64-bit hash keeps the probes independent; pairing FNV-1
	// with FNV-1a instead produced heavily correlated probes and ~4.5% FP at a
	// nominal 1%.
	h1 := h
	h2 := (h >> 32) | 1 // odd so the probe sequence has full period
	m := uint64(bf.numBits)
	for i := 0; i < bf.numHashes; i++ {
		idx := (h1 + uint64(i)*h2) % m
		if (bf.bits[idx/8] & (1 << (idx % 8))) == 0 {
			return false
		}
	}
	return true
}

// hash64 is FNV-1a 64 followed by the splitmix64 finalizer. The finalizer is
// what makes the two 32-bit halves usable as independent double-hashing probes.
func hash64(s string) uint64 {
	const (
		offset64 = 14695981039346656037
		prime64  = 1099511628211
	)
	h := uint64(offset64)
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= prime64
	}
	h ^= h >> 30
	h *= 0xbf58476d1ce4e5b9
	h ^= h >> 27
	h *= 0x94d049bb133111eb
	h ^= h >> 31
	return h
}

var errCorrupt = &bloomError{"corrupt bloom filter data"}

type bloomError struct {
	msg string
}

func (e *bloomError) Error() string {
	return e.msg
}
